"""Generates UnicodeData.h, the grapheme cluster break properties TextLayout segments text with, from a pinned Unicode Character Database.

Run from the repository root when updating Unicode:

    python External/unicode/GenerateUnicodeData.py

It downloads the pinned files, so it is dependency-update tooling, never part of a build.
"""

import re
import urllib.request

VERSION = "17.0.0"
BASE = f"https://www.unicode.org/Public/{VERSION}/ucd"
OUTPUT = "External/unicode/UnicodeData.h"
BREAKS = ["Other", "CR", "LF", "Control", "Extend", "ZWJ", "Regional_Indicator", "Prepend", "SpacingMark", "L", "V", "T", "LV", "LVT"]
CONJUNCTS = ["None", "Consonant", "Extend", "Linker"]


def fetch(path):
    with urllib.request.urlopen(f"{BASE}/{path}") as Response:
        return Response.read().decode("utf-8")


def ranges(Text, Property=None):
    for Line in Text.splitlines():
        Line = Line.split("#")[0].strip()
        if not Line:
            continue

        Fields = [Field.strip() for Field in Line.split(";")]
        if Property and Fields[1] != Property:
            continue

        Bounds = Fields[0].split("..")
        yield int(Bounds[0], 16), int(Bounds[-1], 16), Fields


def main():
    Break = [0] * 0x110000
    Pictographic = [False] * 0x110000
    Conjunct = [0] * 0x110000
    for First, Last, Fields in ranges(fetch("auxiliary/GraphemeBreakProperty.txt")):
        for Code in range(First, Last + 1):
            Break[Code] = BREAKS.index(Fields[1])

    for First, Last, _ in ranges(fetch("emoji/emoji-data.txt"), "Extended_Pictographic"):
        for Code in range(First, Last + 1):
            Pictographic[Code] = True

    for First, Last, Fields in ranges(fetch("DerivedCoreProperties.txt"), "InCB"):
        for Code in range(First, Last + 1):
            Conjunct[Code] = CONJUNCTS.index(Fields[2])

    Rows = []
    Start = 0
    for Code in range(1, 0x110001):
        if Code == 0x110000 or (Break[Code], Pictographic[Code], Conjunct[Code]) != (Break[Start], Pictographic[Start], Conjunct[Start]):
            if Break[Start] or Pictographic[Start] or Conjunct[Start]:
                Rows.append(f"    FGraphemeRange{{0x{Start:X}, 0x{Code - 1:X}, EGraphemeBreak::{BREAKS[Break[Start]]}, {'true' if Pictographic[Start] else 'false'}, EIndicConjunct::{CONJUNCTS[Conjunct[Start]]}}},\n")
            Start = Code

    License = urllib.request.urlopen("https://www.unicode.org/license.txt").read().decode("utf-8")
    LicenseComment = "\n".join(("// " + Line).rstrip() for Line in License.strip().splitlines())
    Header = (
        f"// Generated by External/unicode/GenerateUnicodeData.py from the Unicode Character Database {VERSION}; do not edit.\n"
        "//\n"
        f"{LicenseComment}\n"
        "\n"
        "#pragma once\n"
        "\n"
        "#include <array>\n"
        "#include <cstdint>\n"
        "#include <string_view>\n"
        "\n"
        "namespace Herta::Unicode\n"
        "{\n"
        f"inline constexpr std::string_view Version = \"{VERSION}\";\n"
        "\n"
        "enum class EGraphemeBreak : std::uint8_t\n"
        "{\n"
        + "".join(f"    {Name},\n" for Name in BREAKS)
        + "};\n"
        "\n"
        "enum class EIndicConjunct : std::uint8_t\n"
        "{\n"
        + "".join(f"    {Name},\n" for Name in CONJUNCTS)
        + "};\n"
        "\n"
        "struct FGraphemeRange\n"
        "{\n"
        "    char32_t First;\n"
        "    char32_t Last;\n"
        "    EGraphemeBreak Break;\n"
        "    bool bExtendedPictographic;\n"
        "    EIndicConjunct Conjunct;\n"
        "};\n"
        "\n"
        "// Sorted, disjoint ranges of every code point whose properties are not Other, false, and None.\n"
        # The element type and count are spelled out: deducing an array of this size exceeds Clang's template depth.
        f"inline constexpr std::array<FGraphemeRange, {len(Rows)}> GraphemeRanges{{\n"
        + "".join(Rows)
        + "};\n"
        "}\n"
    )

    with open(OUTPUT, "w", encoding="utf-8", newline="\n") as File:
        File.write(Header)


if __name__ == "__main__":
    main()
